let scenario_state=0;
print('scenario-start:iterator-close');
function scenario_iterable(closeThrows,returnGetter){let cursor=0;const record={next(){print('next:'+cursor);if(cursor===0){record.next=function(){print('replacement-next');throw 77;};}if(cursor>=3)return {done:true};const current=++cursor;return {get value(){print('value:'+current);return current;},done:false};}};const close=function(){print('close:'+cursor);if(closeThrows)throw 23;return {done:true};};if(returnGetter){Object.defineProperty(record,'return',{get(){print('return-get');return close;}});}else{record.return=close;}return {[Symbol.iterator](){print('iterator');return record;}};}
for(let scenario_index=0;scenario_index<1;++scenario_index){
switch(scenario_index){
case 0:{
outer:for(const first of scenario_iterable(false,false)){for(const second of scenario_iterable(false,false)){scenario_state=(scenario_state+first+second)|0;break outer;}}
print('scenario-step:0');
break;}
}
}
